{"command":"cd /workspace && cat > src/game.rs <<'EOF'
use rand::seq::SliceRandom;
use std::time::Instant;

/// Build the text for a new lesson: `combi` randomly picked items (with
/// replacement) from the pool, the whole sequence repeated `rep` times.
/// Every item is followed by a single space.
fn build_text(pool: &[String], combi: usize, rep: usize) -> String {
    let mut rng = rand::thread_rng();
    let mut picked: Vec<&str> = Vec::with_capacity(combi);
    for _ in 0..combi {
        picked.push(pick(pool, &mut rng));
    }
    let mut text = String::new();
    for _ in 0..rep {
        for item in &picked {
            text.push_str(item);
            text.push(' ');
        }
    }
    text
}

fn pick<'a, R: rand::Rng>(pool: &'a [String], rng: &mut R) -> &'a str {
    pool.choose(rng).unwrap().as_str()
}

pub struct Game {
    pool: Vec<String>,
    combi: usize,
    rep: usize,
    pub wpm_threshold: i32,
    pub acc_threshold: i32,

    pub lesson: usize,
    pub text: Vec<char>,
    pub input: Vec<char>,
    start: Option<Instant>,
    errors: usize,
    backspaces: usize,

    pub successes: usize,
    pub failures: usize,
    wpm_history: Vec<u64>,
    acc_history: Vec<u64>,
}

impl Game {
    pub fn new(pool: Vec<String>, combi: usize, rep: usize, wpm: i32, acc: i32) -> Self {
        Game {
            pool,
            combi,
            rep,
            wpm_threshold: wpm,
            acc_threshold: acc,
            lesson: 0,
            text: Vec::new(),
            input: Vec::new(),
            start: None,
            errors: 0,
            backspaces: 0,
            successes: 0,
            failures: 0,
            wpm_history: Vec::new(),
            acc_history: Vec::new(),
        }
    }

    /// The current lesson is finished once the typed input equals the text.
    pub fn is_complete(&self) -> bool {
        self.input == self.text
    }

    /// Record the results of the finished lesson (if any) and start a new one.
    pub fn next_lesson(&mut self) {
        if self.lesson > 0 {
            self.record_results();
        }
        self.lesson += 1;
        self.text = build_text(&self.pool, self.combi, self.rep).chars().collect();
        self.input.clear();
        self.start = None;
        self.errors = 0;
        self.backspaces = 0;
    }

    fn record_results(&mut self) {
        let non_space = self.text.iter().filter(|c| **c != ' ').count();
        let words = non_space as f64 / 5.0;
        let secs = self
            .start
            .map(|s| s.elapsed().as_secs_f64())
            .unwrap_or(0.0);
        let wpm = (words / (secs / 60.0)) as u64;

        let typed = self.text.len() + self.backspaces;
        let total = typed + self.errors;
        let acc = if total == 0 {
            100
        } else {
            (typed as u64 * 100) / total as u64
        };

        if wpm as i64 >= self.wpm_threshold as i64 && acc as i64 >= self.acc_threshold as i64 {
            self.successes += 1;
        } else {
            self.failures += 1;
        }
        self.wpm_history.push(wpm);
        self.acc_history.push(acc);
    }

    pub fn type_char(&mut self, c: char) {
        if !(c.is_alphabetic() || c == ' ') {
            return;
        }
        if self.input.len() >= self.text.len() {
            return;
        }
        if self.input.is_empty() {
            self.start = Some(Instant::now());
        }
        if self.text[self.input.len()] != c {
            self.errors += 1;
        }
        self.input.push(c);
    }

    pub fn backspace(&mut self) {
        if self.input.pop().is_some() {
            self.backspaces += 1;
        }
    }

    fn avg(v: &[u64]) -> u64 {
        if v.is_empty() {
            0
        } else {
            v.iter().sum::<u64>() / v.len() as u64
        }
    }

    pub fn avg_wpm(&self) -> u64 {
        Self::avg(&self.wpm_history)
    }

    pub fn last_wpm(&self) -> u64 {
        self.wpm_history.last().copied().unwrap_or(0)
    }

    pub fn avg_acc(&self) -> u64 {
        Self::avg(&self.acc_history)
    }

    pub fn last_acc(&self) -> u64 {
        self.acc_history.last().copied().unwrap_or(0)
    }
}
EOF
