//! The most important module: an animated companion cat.

/// Static part of the cat (head and body), relative to the cat area.
const HEAD: [&str; 5] = [
    "    /\\_/\\",
    "   >(•༝• )<",
    "    |    \\",
    "    || |  )",
    "    ll-l-//",
];

