/// root of the tail) and the two tail lines.
struct Tail {
    root: &'static str,
    upper: &'static str,
    lower: &'static str,
}

const FRAMES: [Tail; 15] = [
    Tail { root: "||", upper: "         \\\\", lower: "          V" },
    Tail { root: "||", upper: "          \\\\", lower: "           V" },
    Tail { root: "||", upper: "          \\\\", lower: "            >" },
    Tail { root: "\\\\", upper: "          \\__>", lower: "" },
    Tail { root: "\\\\", upper: "          \\__>", lower: "" },
    Tail { root: "||", upper: "          \\\\", lower: "            >" },
    Tail { root: "||", upper: "         \\\\", lower: "          V" },
    Tail { root: "||", upper: "         ||", lower: "         v" },
    Tail { root: "||", upper: "        //", lower: "        V" },
    Tail { root: "||", upper: "        //", lower: "       <" },
    Tail { root: "//", upper: "      <__/", lower: "" },
    Tail { root: "//", upper: "      <__/", lower: "" },
    Tail { root: "||", upper: "        //", lower: "       <" },
    Tail { root: "||", upper: "        //", lower: "        V" },
    Tail { root: "||", upper: "         ||", lower: "         v" },
];

/// The lines of the cat for animation step `tick`.
pub fn frame(tick: usize) -> Vec<String> {
    let tail = &FRAMES[tick % FRAMES.len()];
    let mut lines: Vec<String> = HEAD.iter().map(|l| l.to_string()).collect();
    lines.push(format!("/▔▔▔▔▔▔▔▔{}▔▔\\", tail.root));
    lines.push(tail.upper.to_string());
    lines.push(tail.lower.to_string());
    lines
}
