        return;
    }
    draw_main(frame, app);
}

fn draw_too_small(frame: &mut Frame, app: &App) {
    let text: Vec<Line> = if app.show_kb {
        vec![
            Line::from("Please resize your terminal to at least 80x20,"),
            Line::from("or consider disabling the keyboard display with --nokb"),
            Line::from(""),
            Line::from(" <esc> or <ctrl-c> to quit"),
        ]
    } else {
        vec![
            Line::from("Please resize your terminal to at least 80x13."),
            Line::from(" <esc> or <ctrl-c> to quit"),
        ]
    };
    let paragraph = Paragraph::new(text).alignment(Alignment::Center);
    frame.render_widget(paragraph, frame.area());
}

fn separator() -> Block<'static> {
    Block::new().borders(Borders::TOP)
}

fn draw_main(frame: &mut Frame, app: &App) {
    let game = &app.game;
    let height = if app.show_kb {
        BOX_HEIGHT_KB
    } else {
        BOX_HEIGHT_NOKB
    };
    let outer = Rect::new(0, 0, BOX_WIDTH, height);

    let title = Line::from(vec![
        Span::raw(" Quit "),
        Span::styled(
            "<esc> ",
            Style::default()
                .fg(Color::Blue)
                .add_modifier(Modifier::BOLD),
        ),
    ])
    .right_aligned();
    let block = Block::bordered()
        .border_type(BorderType::Rounded)
        .title_top(title);
    let inner = block.inner(outer);
    frame.render_widget(block, outer);

    let kb_rows = if app.show_kb { 7 } else { 1 };
    let rows = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(1), // header
            Constraint::Length(1), // separator
            Constraint::Length(1), // lesson line
            Constraint::Length(1), // separator
            Constraint::Length(1), // empty
            Constraint::Length(1), // text to type
            Constraint::Length(1), // typed input
            Constraint::Length(kb_rows),
            Constraint::Length(1), // separator
            Constraint::Length(2), // statistics
        ])
        .split(inner);

    // header
    let header = Line::from(vec![
        Span::styled(
            "               ngrrram!",
            Style::default().add_modifier(Modifier::BOLD),
        ),
        Span::styled(
            "   by winterveil",
            Style::default()
                .fg(Color::Gray)
                .add_modifier(Modifier::ITALIC),
        ),
    ]);
    frame.render_widget(
        Paragraph::new(header).alignment(Alignment::Center),
        rows[0],
    );
    frame.render_widget(separator(), rows[1]);

    // lesson line
    let halves = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
        .split(rows[2]);
    frame.render_widget(
        Paragraph::new(format!("    Lesson #{}", game.lesson)),
        halves[0],
    );
    let score = Line::from(vec![
        Span::styled(
            format!("✔: {}, ", game.successes),
            Style::default().fg(Color::Green),
        ),
        Span::styled(
            format!("✘: {}    ", game.failures),
            Style::default().fg(Color::Red),
        ),
    ]);
    frame.render_widget(
        Paragraph::new(score).alignment(Alignment::Right),
        halves[1],
    );
    frame.render_widget(separator(), rows[3]);

    // the text to type, coloured by correctness
    let bold = Style::default().add_modifier(Modifier::BOLD);
    let mut spans: Vec<Span> = Vec::with_capacity(game.text.len());
    for (i, &c) in game.text.iter().enumerate() {
        match game.input.get(i) {
            Some(&typed) if typed == c => {
                spans.push(Span::styled(c.to_string(), bold.fg(Color::Green)));
            }
            Some(_) => {
                let shown = if c == ' ' { '•' } else { c };
                spans.push(Span::styled(shown.to_string(), bold.fg(Color::Red)));
            }
            None => spans.push(Span::styled(c.to_string(), bold)),
        }
    }
    frame.render_widget(
        Paragraph::new(Line::from(spans)).alignment(Alignment::Center),
        rows[5],
    );

    // what has been typed: only mistakes are shown
    let mut typed_line = String::with_capacity(game.text.len());
    for (i, &c) in game.text.iter().enumerate() {
        match game.input.get(i) {
            Some(&typed) if typed != c => typed_line.push(typed),
            _ => typed_line.push(' '),
        }
    }
    frame.render_widget(
        Paragraph::new(typed_line).style(
            Style::default()
                .fg(Color::Gray)
                .add_modifier(Modifier::ITALIC),
        ).alignment(Alignment::Center),
        rows[6],
    );

    // cursor at the current position within the text
    let text_len = game.text.len() as i32;
    let cursor_x = rows[5].x as i32 + (rows[5].width as i32 - text_len) / 2 + game.input.len() as i32;
    frame.set_cursor_position(Position::new(cursor_x as u16, rows[5].y));

    // keyboard
    if app.show_kb {
        let kb_area = if app.show_cat {
            Layout::default()
                .direction(Direction::Horizontal)
                .constraints([
                    Constraint::Length(5),
                    Constraint::Length(55),
                    Constraint::Min(0),
                ])
                .split(rows[7])[1]
        } else {
            Layout::default()
                .direction(Direction::Horizontal)
                .constraints([Constraint::Length(13), Constraint::Min(0)])
                .split(rows[7])[1]
        };
        let layout = layouts::by_name(app.displayed_layout());
        let art = if app.show_ortho {
            layouts::ortho_art(&layout)
        } else {
            layouts::staggered_art(&layout)
        };
        let lines: Vec<Line> = art.into_iter().map(Line::from).collect();
        frame.render_widget(
            Paragraph::new(lines).style(Style::default().fg(Color::Gray)),
            kb_area,
        );
    }

    frame.render_widget(separator(), rows[8]);

    // statistics
    let gray = Style::default().fg(Color::Gray);
    let wpm_line = Line::from(vec![
        Span::styled(
            format!("  need >= {:>3}WPM,   avg. ", game.wpm_threshold),
            gray,
        ),
        Span::raw(format!("{:>3}WPM", game.avg_wpm())),
        Span::styled(",   last", gray),
        Span::raw(format!(" {:>3}WPM", game.last_wpm())),
    ]);
    let acc_line = Line::from(vec![
        Span::styled(
            format!("  need >= {:>3}% Acc, avg. ", game.acc_threshold),
            gray,
        ),
        Span::raw(format!("{:>3}% Acc", game.avg_acc())),
        Span::styled(", last", gray),
        Span::raw(format!(" {:>3}% Acc", game.last_acc())),
    ]);
    frame.render_widget(Paragraph::new(vec![wpm_line, acc_line]), rows[9]);

    // the cat lives in the lower right corner, drawn over everything else
    if app.show_cat {
        let cat_area = Rect::new(61, 10, 17, outer.height.saturating_sub(10));
        let lines: Vec<Line> = cat::frame(app.tick).into_iter().map(Line::from).collect();
        frame.render_widget(Paragraph::new(lines), cat_area);
    }
}
