use game::Game;

const TICK_RATE: Duration = Duration::from_millis(160);

fn cli() -> Command {
    Command::new("ngrrram")
        .arg(
            Arg::new("n")
                .short('n')
                .long("n")
                .value_name("2|3|4|w|file")
                .default_value("2")
                .help("use bi-(2), tri-(3), tetragrams(4), (w)ords or comma separated wordlist file."),
        )
        .arg(
