                .short('t')
                .long("top")
                .value_name("1-200")
                .default_value("50")
                .value_parser(value_parser!(i32))
                .help("use the top X ngrams ordered by usage."),
        )
        .arg(
            Arg::new("combi")
                .short('c')
                .long("combi")
                .value_name("1-200")
                .default_value("2")
                .value_parser(value_parser!(i32))
                .help("how many different ngrams to use in a single lesson."),
        )
        .arg(
            Arg::new("rep")
                .short('r')
                .long("rep")
                .value_name("number")
                .default_value("3")
                .value_parser(value_parser!(i32))
                .help("how often to repeat *each* different ngram in a lesson."),
        )
        .arg(
            Arg::new("wpm")
                .short('w')
                .long("wpm")
                .value_name("number")
                .default_value("40")
                .value_parser(value_parser!(i32))
                .help("the wpm threshold at which the lesson is considered a success."),
        )
        .arg(
            Arg::new("acc")
                .short('a')
                .long("acc")
                .value_name("0-100")
                .default_value("94")
                .value_parser(value_parser!(i32))
                .help("the accuracy in percent at which the lesson is considered a success."),
        )
        .arg(
            Arg::new("emu-in")
                .long("emu-in")
                .value_name("layout")
                .default_value("")
                .help("your current keyboard layout. only needed if you want to emulate a different layout. see docs for supported layouts."),
        )
        .arg(
            Arg::new("emu-out")
                .long("emu-out")
                .value_name("layout")
                .default_value("")
                .help("the layout you want to emulate. only needed if you want to emulate a different layout. see docs for supported layouts."),
        )
        .arg(
            Arg::new("show-ortho")
                .long("show-ortho")
                .action(ArgAction::SetTrue)
                .help("show keyboard in ortholinear format"),
        )
        .arg(
            Arg::new("nokb")
                .long("nokb")
                .action(ArgAction::SetTrue)
                .help("pass this flag to disable the keyboard layout display."),
        )
        .arg(
            Arg::new("cat")
                .long("cat")
                .action(ArgAction::SetTrue)
                .help("the most important flag. don't practice alone."),
        )
}

fn check_range(name: &str, value: i32, min: i32, max: i32) {
    if value < min || value > max {
        println!(
            "Invalid argument for {}. Use a number between {} and {}.",
            name, min, max
        );
        process::exit(1);
    }
}

/// Load the list of items to practice. Built-in lists are selected with
/// `2`, `3`, `4` and `w`; anything else is a path to a comma separated file.
fn load_pool(n: &str, top: usize) -> Vec<String> {
    let all: Vec<String> = match n {
        "2" => data::BIGRAMS.iter().map(|s| s.to_string()).collect(),
        "3" => data::TRIGRAMS.iter().map(|s| s.to_string()).collect(),
        "4" => data::TETRAGRAMS.iter().map(|s| s.to_string()).collect(),
        "w" => data::WORDS.iter().map(|s| s.to_string()).collect(),
        path => match std::fs::read_to_string(path) {
            Ok(content) => content
                .lines()
                .flat_map(|line| line.split(',').map(|s| s.to_string()).collect::<Vec<_>>())
                .collect(),
            Err(_) => {
                println!("File not found: {}", path);
                process::exit(1);
            }
        },
    };
    let count = top.min(all.len());
    all[..count].to_vec()
}

fn main() -> io::Result<()> {
    let matches = cli().get_matches();

    let n = matches.get_one::<String>("n").cloned().unwrap_or_default();
    let top = *matches.get_one::<i32>("top").unwrap();
    let combi = *matches.get_one::<i32>("combi").unwrap();
    let rep = *matches.get_one::<i32>("rep").unwrap();
    let wpm = *matches.get_one::<i32>("wpm").unwrap();
    let acc = *matches.get_one::<i32>("acc").unwrap();
    let emu_in = matches.get_one::<String>("emu-in").cloned().unwrap_or_default();
    let emu_out = matches.get_one::<String>("emu-out").cloned().unwrap_or_default();
    let show_ortho = matches.get_flag("show-ortho");
    let nokb = matches.get_flag("nokb");
    let show_cat = matches.get_flag("cat");

    check_range("top", top, 1, 200);
    check_range("combi", combi, 1, 200);
    check_range("rep", rep, 1, 200);
    check_range("wpm", wpm, 1, 200);
    check_range("acc", acc, 0, 100);

    if emu_in.is_empty() != emu_out.is_empty() {
        println!("You need to specify both emu_in and emu_out.");
        process::exit(1);
    }

    let pool = load_pool(&n, top as usize);
    let game = Game::new(pool, combi as usize, rep as usize, wpm, acc);
    let mut app = App::new(game, !nokb, show_ortho, show_cat, emu_in, emu_out);

    // terminal setup
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    enable_raw_mode()?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let result = run(&mut terminal, &mut app);

    // restore the terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    result
}

fn run(terminal: &mut Terminal<CrosstermBackend<io::Stdout>>, app: &mut App) -> io::Result<()> {
    let mut last_tick = Instant::now();
    loop {
        terminal.draw(|frame| ui::draw(frame, app))?;

        if app.game.is_complete() {
            app.game.next_lesson();
            continue;
        }

        let timeout = TICK_RATE.saturating_sub(last_tick.elapsed());
        if event::poll(timeout)? {
            if let Event::Key(key) = event::read()? {
                if key.kind != KeyEventKind::Release {
                    match key.code {
                        KeyCode::Esc => return Ok(()),
                        KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                            return Ok(())
                        }
                        KeyCode::Char(c) => {
                            let mods = key.modifiers - KeyModifiers::SHIFT;
                            if mods.is_empty() {
                                app.type_char(c);
                            }
                        }
                        KeyCode::Enter => app.type_char(' '),
                        KeyCode::Backspace => app.game.backspace(),
                        _ => {}
                    }
                }
            }
        }

        if last_tick.elapsed() >= TICK_RATE {
            app.on_tick();
            last_tick = Instant::now();
        }
    }
}
