    if emu_in.is_empty() != emu_out.is_empty() {
        println!("You need to specify both emu_in and emu_out.");
        process::exit(1);
    }

    let pool = load_pool(&n, top as usize);
    let game = Game::new(pool, combi as usize, rep as usize, wpm, acc);
    let mut app = App::new(game, !nokb, show_ortho, show_cat, emu_in, emu_out);

    // terminal setup
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    enable_raw_mode()?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let result = run(&mut terminal, &mut app);

    // restore the terminal
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;

    result
}

fn run(terminal: &mut Terminal<CrosstermBackend<io::Stdout>>, app: &mut App) -> io::Result<()> {
    let mut last_tick = Instant::now();
    loop {
        terminal.draw(|frame| ui::draw(frame, app))?;

        if app.game.is_complete() {
            app.game.next_lesson();
            continue;
        }

        let timeout = TICK_RATE.saturating_sub(last_tick.elapsed());
        if event::poll(timeout)? {
            if let Event::Key(key) = event::read()? {
                if key.kind != KeyEventKind::Release {
                    match key.code {
                        KeyCode::Esc => return Ok(()),
                        KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                            return Ok(())
                        }
                        KeyCode::Char(c) => {
                            let mods = key.modifiers - KeyModifiers::SHIFT;
                            if mods.is_empty() {
                                app.type_char(c);
                            }
                        }
                        KeyCode::Enter => app.type_char(' '),
                        KeyCode::Backspace => app.game.backspace(),
                        _ => {}
                    }
                }
            }
        }

        if last_tick.elapsed() >= TICK_RATE {
            app.on_tick();
            last_tick = Instant::now();
        }
    }
}
